function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const Q = nextInt();

    const bit = new Int32Array(N + 1);
    const A = new Int32Array(N + 1);

    function add(idx, val) {
        for (; idx <= N; idx += idx & -idx) {
            bit[idx] += val;
        }
    }

    function query(idx) {
        let sum = 0;
        for (; idx > 0; idx -= idx & -idx) {
            sum += bit[idx];
        }
        return sum;
    }

    for (let i = 1; i <= N; i++) {
        const val = nextInt();
        A[i] = val;
        bit[i] += val;
        const parent = i + (i & -i);
        if (parent <= N) {
            bit[parent] += bit[i];
        }
    }

    let out = [];
    for (let q = 0; q < Q; q++) {
        const type = nextInt();
        if (type === 0) {
            const K = nextInt();
            const P = nextInt();
            const diff = P - A[K];
            A[K] = P;
            add(K, diff);
        } else {
            const K = nextInt();
            out.push(query(K));
            if (out.length >= 10000) {
                process.stdout.write(out.join('\n') + '\n');
                out = [];
            }
        }
    }

    if (out.length > 0) {
        process.stdout.write(out.join('\n') + '\n');
    }
}

